function demoSpec(t){const T0=V.types[t],d=DK[T0.demo.k]||DK.cat,sp=norm(JSON.parse(JSON.stringify(d)));sp.type=t;sp.opt=Object.assign({},sp.opt,T0.demo.opt||{});if(T0.demo.k==="cat"&&/pie|donut|waffle|shape_stack|person_waffle/.test(t)){sp.enc={x:"priority",y:"cost"};sp.agg="sum";sp.limit=0}if(t==="funnel"){sp.enc={x:"priority",y:"users"};sp.agg="sum"}if(t==="pareto"){sp.enc={x:"category",y:"cost"};sp.agg="sum"}if(t==="waterfall"){sp.enc={x:"category",y:"cost"};sp.agg="sum"}if(t==="bullet"||t==="diverge"||t==="lollipop"||t==="radial_bar"||t==="polar_area"){sp.limit=6}if(t==="pyramid"){sp.limit=8}if(t==="shape_bars"||t==="pictogram"||t==="pictorial_bar"||t==="shape_stack"){sp.src="cars";sp.n=0;sp.enc={x:t==="shape_stack"?"region":"model",y:"units"};sp.agg="sum";sp.opt.shape=t==="pictogram"||t==="pictorial_bar"?"car":"car"}if(t==="calendar"){sp.enc={x:"opened"};sp.agg="count"}if(t==="candlestick"){sp.grain="day"}if(t==="map_coverage"){sp.opt.geo="us"}if(t==="dumbbell"){sp.enc={x:"service",color:"site"};sp.agg="avg";sp.enc.y="hours";sp.limit=6}if(t==="cfd"){sp.enc={x:"opened",color:"priority"};sp.agg="count"}if(t==="swimlane"||t==="roadmap"){sp.enc.color="team"}if(t==="venn"){sp.enc={x:"service",color:"priority"}}if(t==="status_matrix"){sp.enc={x:"service",color:"priority"};sp.agg="avg";sp.enc.y="hours"}if(t==="heatmap"||t==="matrix_dots"){sp.enc={x:"service",color:"priority"};sp.agg="count"}if(t==="treemap"||t==="sunburst"||t==="icicle"){sp.enc={x:"service",color:"category",y:"cost"};sp.agg="sum";sp.limit=0}if(t==="packed"){sp.enc={x:"service",y:"cost"};sp.agg="sum"}if(t==="marimekko"){sp.enc={x:"service",color:"priority"};sp.agg="count"}if(t==="chord"||t==="arc"||t==="sankey"||t==="network"){if(sp.src==="inc"){sp.enc={x:"service",color:"category"};sp.agg="count"}}if(t==="alluvial"){sp.enc={x:"site",color:"service",shape:"category"}}if(t==="tree"||t==="dendrogram"||t==="orgchart"){sp.enc={x:"name",color:"mgr"}}if(t==="histogram"){sp.enc={x:"hours"};sp.bin=14}if(t==="small_multiples"){sp.grain="month"}if(t==="slope"){sp.grain="month"}if(t==="bump"){sp.grain="month";sp.agg="count";sp.enc.color="service"}if(t==="stream"||t==="area_stacked"||t==="area_100"){sp.grain="month"}if(t==="map_points"||t==="map_hex"||t==="map_bubble_us"||t==="map_us"){sp.opt.geo="us"}if(t==="map_bubble_w"){sp.enc={x:"country"}}return sp}
V.demoSpec=demoSpec;
const GOV=sp=>{const s=getSrc(sp.src);if(!s)return false;if(sp.src.startsWith("m:")||sp.src.startsWith("dm:")||s.dm||s.metric)return true;const yf=s.fields.find(f=>f.k===sp.enc.y);return !!(yf&&yf.m)};
function recommend(sp){const s=getSrc(sp.src);if(!s)return [];const F={};s.fields.forEach(f=>F[f.k]=f);sp.calc.forEach(c=>F[c.k]={k:c.k,label:c.label||c.k,t:"n"});const en=sp.enc,xf=F[en.x],yf=F[en.y],cf=F[en.color],rows=rowsOf(s,s.big?Z.bigN:0),card=k=>k?new Set(rows.slice(0,3000).map(r=>r[k])).size:0;const out=[];const add=(t,sc,why)=>{if(V.types[t]&&!out.some(o=>o.t===t))out.push({t,s:sc,why})};const hasLL=s.fields.some(f=>f.geo==="lat")&&s.fields.some(f=>f.geo==="lon"),big=rows.length>5000;
 if(xf&&xf.t==="d"){add("line",.95,"A date on X and a measure on Y is a trend over time, which a line shows best.");if(cf){add("area_stacked",.82,"A color field splits the total over time into parts.");add("bump",.5,"Shows how the rank of each "+cf.label.toLowerCase()+" changes.");add("spark_grid",.6,"Many small trends at once, each with its latest value.")}else add("area",.8,"Area adds volume under the line when there is a single series.");add("bar",.62,"Bars work when there are only a handful of periods.");add("calendar",.55,"Daily values are easy to scan as a calendar.");add("control",.5,"Flags unusual points against control limits.");add("timeline",.45,"Shows when events happened.")}
 if(xf&&xf.t==="c"&&!xf.geo){const c=card(en.x);if(c<=6){add("bar",.88,"Few groups: bars compare them honestly.");add("donut",yf&&sp.agg==="avg"?.3:.66,"Shares of a total read well with about six or fewer slices.")}else if(c<=24){add("bar_h",.92,c+" groups: horizontal bars keep every label readable.");add("treemap",.7,"Rectangles scale to many groups.");add("lollipop",.62,"A lighter way to show many ranked values.")}else{add("treemap",.85,c+" groups is too many for bars; a treemap or Pareto keeps the big ones visible.");add("pareto",.8,"Shows which few groups account for most of the total.");add("table_bars",.7,"A ranked table keeps exact values.")}
  if(cf&&cf.t==="c"){add("bar_stacked",.86,"Two category fields: stack one inside the other.");add("heatmap",.8,"A grid of the two fields shows hot spots.");add("sankey",.64,"Shows how "+xf.label.toLowerCase()+" flows into "+cf.label.toLowerCase()+".");add("marimekko",.5,"Column width is the size, height is the mix.");add("chord",.45,"Relationships between the two fields around a circle.");add("venn",.4,"Which items sit in several sets.")}
  if(yf&&yf.t==="n"&&big)add("box",.6,"Thousands of records per group: show the spread, not just the average.")}
 if(xf&&xf.t==="n"&&yf&&yf.t==="n"){add(big?"hexbin":"scatter",.96,big?"Over 5,000 points: hexagons keep it readable while the scatter would overplot.":"Two numeric fields: a scatter shows relationship and outliers.");add(big?"density":"hexbin",.78,"Shows where records concentrate.");if(en.size)add("bubble",.9,"A third measure becomes the dot size.");else add("bubble",.55,"Add a Size field to turn dots into bubbles.");add("contour",.45,"Contour lines around dense regions.");add("parallel",.4,"Compare profiles across several measures.");add("correlogram",.5,"How every pair of numeric fields move together.")}
 if(xf&&xf.geo){add(xf.geo==="us"?"map_us":"map_world",.97,xf.label+" is a place: a map shows geographic coverage.");add(xf.geo==="us"?"map_bubble_us":"map_bubble_w",.8,"Proportional circles make counts easy to compare.");add("bar_h",.6,"Ranked bars give exact order.")}
 if(hasLL){add("map_points",.9,"Latitude and longitude are present: plot each record, clustered when dense.");add("map_hex",big?.88:.7,"Hexagons summarize points over the map.")}
 if((!xf||!xf.geo&&xf.t==="n"&&!yf)&&(yf&&yf.t==="n"||xf&&xf.t==="n")){add("histogram",xf&&!yf?.95:.7,"One numeric field: see how values are distributed.");add("kpi",.7,"Or summarize it as one number against a target.");add("gauge",.6,"Add a target and show good, watch and act bands.")}
 if(!xf&&!yf){add("kpi",.6,"Pick a measure to see a single big number.");add("bar",.5,"Pick a category for X to compare groups.")}
 if(sp.src==="flows"){add("map_flow",.97,"Both ends of each link have coordinates.")}
 if(en.x&&en.y&&F[en.y]&&F[en.y].t==="d"&&F[en.y2||""]&&F[en.y2].t==="d"){add("gantt",.97,"Two date fields per row are a start and a finish.");add("swimlane",.8,"Group the bars into lanes.");add("roadmap",.7,"A leadership view of what lands when.")}
 if(!out.length){add("bar",.6,"A safe default.");add("table_bars",.5,"A table keeps exact numbers.")}
 return out.sort((a,b)=>b.s-a.s).slice(0,6)}
function lint(sp){const out=[],s=getSrc(sp.src),T0=V.types[sp.type];if(!s)return [["bad","Unknown data source."]];const F={};s.fields.forEach(f=>F[f.k]=f);const en=sp.enc,xf=F[en.x],yf=F[en.y];const rows=rowsOf(s,s.big?Z.bigN:0);
 if(!sp.title&&!sp.sub)out.push(["info","Add a title that says what to conclude, not just what is plotted."]);
 if((sp.type==="line"||sp.type==="area")&&xf&&xf.t==="c")out.push(["warn","Lines imply an order. “"+xf.label+"” has none; use bars or sort by a date."]);
 if(/^(pie|donut|waffle)$/.test(sp.type)&&xf){const c=new Set(rows.slice(0,3000).map(r=>r[en.x])).size;if(c>6)out.push(["warn",c+" slices is too many; the smallest are grouped into Other. Bars read better above six."])}
 if(/^(pie|donut|waffle|person_waffle|shape_stack)$/.test(sp.type)&&sp.agg&&sp.agg!=="sum"&&sp.agg!=="count")out.push(["warn","Shares of an average or median do not add up to a whole. Use sum or count."]);
 if((sp.type==="scatter"||sp.type==="bubble")&&rows.length>2500)out.push(["info",rows.length.toLocaleString("en-US")+" points: drawn on a canvas for speed. Hexbin or density would show concentration better."]);
 if(rows.length>20000&&/^(scatter|bubble|parallel)$/.test(sp.type))out.push(["warn","Very dense. Switch to hexbin or density so the pattern is not hidden by overplotting."]);
 if(sp.pal==="brand"&&en.color&&F[en.color]&&new Set(rows.slice(0,2000).map(r=>r[en.color])).size>4)out.push(["info","More than four colors: choose the color-blind safe palette so every series stays distinct."]);
 if(yf&&!yf.m&&!yf.dm&&!(s.dm||s.metric))out.push(["info","The measure is not bound to a registered metric. Register it in Metrics so its formula shows on hover."]);
 if(T0&&T0.need&&(!en.x&&!en.y)&&!/^(map_points|map_hex|map_flow|map_rack|map_floor|map_heat|correlogram|parallel|kpi|gauge|speedometer|progress|ring|histogram|shape_fill|shape_liquid|shape_image|shape_custom|calendar)$/.test(sp.type))out.push(["warn","This type "+T0.need+"."]);
 if(!out.length||out.every(o=>o[0]==="info"))out.push(["good","Passes chart checks: every number is traceable, labels are readable, a data table and text alternative are included."]);return out}
