const MAPT=[["map_us","US states"],["map_world","World"],["map_bubble_us","US bubbles"],["map_bubble_w","World bubbles"],["map_points","Points and clusters"],["map_hex","Hex bins"],["map_coverage","On-call coverage"],["map_flow","Replication flows"],["map_rack","Rack elevation"],["map_floor","Floor plan"],["map_heat","Heat overlay"]];
const MAPSRC={map_us:["inc","state"],map_world:["inc","country"],map_bubble_us:["inc","state"],map_bubble_w:["inc","country"],map_points:["inc",null],map_hex:["inc",null],map_coverage:["cov","area"],map_flow:["flows",null],map_rack:["racks",null],map_floor:["floor",null],map_heat:["floor",null]};
function mapSpec(){const t=Z.map,m=MAPSRC[t];let sp=Z.mapSpec&&Z.mapSpec.type===t?Z.mapSpec:null;if(!sp){sp=norm({type:t,src:m[0],enc:{},agg:"count",title:(MAPT.find(x=>x[0]===t)||[0,t])[1]+" map"});if(m[1])sp.enc.x=m[1];if(t==="map_points"||t==="map_hex"){sp.enc.color="priority";sp.opt.geo="us"}if(t==="map_us"||t==="map_bubble_us"){sp.opt.geo="us"}if(t==="map_coverage"){sp.enc={x:"area",color:"tier"};sp.opt.geo=Z.covKind||"us"}if(t==="map_flow"){sp.enc.y="gb"}if(t==="map_rack")sp.enc.color="status";if(t==="map_floor")sp.enc.color="status";if(t==="map_heat")sp.enc.y="temp";Z.mapSpec=sp}return sp}
function pane1(){const sp=mapSpec(),isInc=sp.src==="inc";const inc=getSrc("inc"),rows=rowsOf(inc,0);const f=Z.filt;const regions=(()=>{const m=new Map();rows.forEach(r=>{const k=sp.type==="map_world"||sp.type==="map_bubble_w"?r.country:r.state;if(!k)return;let a=m.get(k);if(!a)m.set(k,a={region:k,n:0,p1:0,h:0,cost:0});a.n++;if(r.priority==="P1")a.p1++;a.h+=r.hours;a.cost+=r.cost});return [...m.values()].map(a=>({region:a.region,n:a.n,p1:a.p1,hrs:r1(a.h/a.n),cost:Math.round(a.cost)}))})();
 const sel=f&&(f.k==="state"||f.k==="country")?f.v:null;const f2=Object.assign({},sp);
 return `${card("Maps: coverage and incidents","Geometry is precomputed and embedded, so every map works offline. Select a region and every other visual on this page filters to it.",`<div class="viz-maptop"><div class="fchips" role="group" aria-label="Map type">${MAPT.map(m=>`<button type="button" class="chip" data-viz-map="${m[0]}" aria-pressed="${Z.map===m[0]}">${m[1]}</button>`).join("")}</div><div class="row sp" data-viz-banner>${bannerHTML()}</div></div><div class="viz-maprow"><div class="viz-mapmain">${V.html(Object.assign({},sp),null,{minh:420,wheel:true,sub:"Hold Shift and scroll, or use the + and − buttons, to zoom. Drag to pan."})}</div><div class="viz-mapside"><h4 class="eyebrow">What is behind this map</h4><p class="muted small">${E(srcName(sp.src))}. ${E((getSrc(sp.src)||{}).lin||"")}</p><div class="legendbox">${legend([["Low","--p6"],["High","--p1"]])}</div>${sel?`<div class="mini glass"><small>Selected</small><b>${E(sel)}</b><span class="muted small">Linked visuals below are filtered to this region.</span></div>`:""}<button class="btn" data-viz-newmapvis>Save this map to the library</button><button class="btn quiet" data-viz-editmap>Edit in the builder</button></div></div>`,`<button class="btn quiet" data-viz-bigmap>Stress test with ${(100000).toLocaleString("en-US")} points</button>`)}
 ${card("Linked visuals","These redraw when you pick a region. The same filter feeds the dashboards tab.",`<div class="grid g2">${V.html({type:"bar_h",src:"inc",enc:{x:"service"},agg:"count",title:"Incidents by service"},null,{minh:240})}${V.html({type:"donut",src:"inc",enc:{x:"priority"},agg:"count",title:"Incidents by priority"},null,{minh:240})}</div>`)}
 ${card("Regions","Sorted, searchable and exportable. Select a row to filter the whole screen.",btHTML({id:"viz_reg",rows:regions,key:"region",h:300,rowH:44,exportName:"incidents-by-region",open:id=>V.setFilter(sp.type==="map_world"||sp.type==="map_bubble_w"?"country":"state",id),cols:[{k:"region",label:"Region",fmt:r=>`<b>${E(r.region)}</b>`},{k:"n",label:"Incidents",fmt:r=>`<span class="num">${r.n}</span>`,val:r=>r.n},{k:"p1",label:"P1 incidents",val:r=>r.p1},{k:"hrs",label:"Avg hours to resolve",val:r=>r.hrs},{k:"cost",label:"Cost",fmt:r=>money(r.cost),val:r=>r.cost}]}),`<span class="pill metric">${regions.length} regions</span>`)}`}
