function shapeSpec(){const z=Z.shp;const sp=norm({type:z.mode,src:z.src,enc:{x:z.x,y:z.y},agg:"sum",limit:z.mode==="shape_bars"?8:0,opt:{shape:z.shape,img:z.img,unit:z.unit||"",target:z.target||"",pct:z.pct},title:z.title||undefined});if(z.mode==="shape_fill"||z.mode==="shape_liquid"||z.mode==="shape_custom"||z.mode==="shape_image"){sp.enc={x:null,y:z.y};sp.opt.target=z.target||""}return sp}
Object.assign(Z.shp,{src:"cars",x:"model",y:"units",target:"",unit:"",img:null,title:""});
